environmentModule.text:
local getArgs = require("Module:Arguments").getArgs

local p = {}

local conditions = {
    ["acid storms"] = {
        file = "Acid Storms Environmental Condition Icon.svg",
        page = "Acid Storms",
        desc = "'''[[Acid Storms]]''' – Corrosive acid storms <span style=color:var(--wiki-custom-emphasis-color)>temporarily reduce armor effectiveness</span> for both enemy and friendly units."
    },
    ["blizzards"] = {
        file = "Blizzards Environmental Condition Icon.svg",
        page = "Blizzards",
        desc = "'''[[Blizzards]]''' – Intense blizzards <span style=color:var(--wiki-custom-emphasis-color)>reduce mobility</span> and <span style=color:var(--wiki-custom-emphasis-color)>moderately reduce visibility</span> for both enemy and friendly units."
    },
    ["extreme cold"] = {
        file = "Extreme Cold Environmental Condition Icon.svg",
        page = "Extreme Cold",
        desc = "'''[[Extreme Cold]]''' – Periods of freezing temperatures <span style=color:var(--wiki-custom-emphasis-color)>reduce rate of fire</span> and <span style=color:var(--wiki-custom-emphasis-color)>delay heat buildup in weapons</span>."
    },
    ["fire tornados"] = {
        file = "Fire Tornados Environmental Condition Icon.svg",
        page = "Fire Tornados",
        desc = "'''[[Fire Tornados]]''' – Planet is ravaged by <span style=color:var(--wiki-custom-emphasis-color)>deadly fire tornados</span>."
    },
    ["intense heat"] = {
        file = "Intense Heat Environmental Condition Icon.svg",
        page = "Intense Heat",
        desc = "'''[[Intense Heat]]''' – Periods of high temperatures <span style=color:var(--wiki-custom-emphasis-color)>increase stamina drain</span> and <span style=color:var(--wiki-custom-emphasis-color)>speed up heat buildup in weapons</span>."
    },
    ["ion storms"] = {
        file = "Ion Storms Environmental Condition Icon.svg",
        page = "Ion Storms",
        desc = "'''[[Ion Storms]]''' – Ion storms intermittently <span style=color:var(--wiki-custom-emphasis-color)>disable Stratagems</span>."
    },
    ["meteor storms"] = {
        file = "Meteor Storms Environmental Condition Icon.svg",
        page = "Meteor Storms",
        desc = "'''[[Meteor Storms]]''' – Meteors impact the surface <span style=color:var(--wiki-custom-emphasis-color)>causing massive damage</span>."
    },
    ["rainstorms"] = {
        file = "Rainstorms Environmental Condition Icon.svg",
        page = "Rainstorms",
        desc = "'''[[Rainstorms]]''' – Torrential rainstorms <span style=color:var(--wiki-custom-emphasis-color)>reduce visibility</span>."
    },
    ["sandstorms"] = {
        file = "Sandstorms Environmental Condition Icon.svg",
        page = "Sandstorms",
        desc = "'''[[Sandstorms]]''' – Dense sandstorms <span style=color:var(--wiki-custom-emphasis-color)>reduce mobility</span> and <span style=color:var(--wiki-custom-emphasis-color)>greatly reduce visibility</span> for both enemy and friendly units."
    },
    ["thick fog"] = {
        file = "Thick Fog Environmental Condition Icon.svg",
        page = "Thick Fog",
        desc = "'''[[Thick Fog]]''' – Dense fog <span style=color:var(--wiki-custom-emphasis-color)>lightly reduces visibility</span> for both enemy and friendly units."
    },
    ["tremors"] = {
        file = "Tremors Environmental Condition Icon.svg",
        page = "Tremors",
        desc = "'''[[Tremors]]''' – Frequent earthquakes <span style=color:var(--wiki-custom-emphasis-color)>stun players and enemies</span> alike."
    },
    ["volcanic activity"] = {
        file = "Volcanic Activity Environmental Condition Icon.svg",
        page = "Volcanic Activity",
        desc = "'''[[Volcanic Activity]]''' – Volcanos <span style=color:var(--wiki-custom-emphasis-color)>throw burning rocks</span> around this planet."
    },
    ["heavy gloom shroud"] = {
        file = "Generic Effect Icon.png",
        page = "The Gloom",
        desc = "'''[[The Gloom|Heavy Gloom Shroud]]''' This planet is completely engulfed by the Gloom, severely impeding logistical support. Extraction times are increased by 40 seconds, Eagle Re-arm time is increased by 30% and Ammo from pickups is reduced by 50%."
    },
    ["none"] = {
        file = "Generic Effect Icon.png",
        page = "None",
        desc = "'''None'''"
    }
}

local generic_icon = "Generic Effect Icon.png"

local function switch(envDesc)
    local key = string.lower(envDesc or "")
    if conditions[key] then
        return conditions[key].desc
    else
        return "Unknown Condition"
    end
end

function p.main(frame)
    local args = getArgs(frame)
    return p._main(args)
end

function p._main(args)
    local output = ""
    for _, arg in ipairs(args) do
        local key = string.lower(arg or "")
        local data = conditions[key]
        local description = switch(arg)

        if key == "none" then
            output = output .. string.format(
                '<span class="faction-icon">[[File:%s|50px|link=]] %s</span><br>',
                generic_icon, description
            )
        elseif data then
            output = output .. string.format(
                '<span class="faction-icon">[[File:%s|50px|link=%s]] %s</span><br>',
                data.file, data.page, description
            )
        elseif description ~= "Unknown Condition" then
            output = output .. string.format(
                '<span class="faction-icon">[[File:%s|50px|link=%s]] %s</span><br>',
                generic_icon, arg, description
            )
        else
            output = output .. string.format(
                '<span class="faction-icon">[[File:%s|50px|link=%s]] %s</span>',
                generic_icon, arg, arg
            )
        end
    end
    return output
end

return p
